/* Maps use a browser-restricted key supplied at runtime, never embedded in source. */
const RTMaps=(()=>{
 let loader=null,map=null,host=null,markers=[],byId=new Map(),info=null,fitBounds=null,sequence=0,authFailed=false;
 const colors={high:'#d32f2f',medium:'#ed8500',low:'#268547',reference:'#606a78'};
 function classify(e){
  const manual=RTCRM.get(e.id).level;if(manual)return {level:'manual'+manual,label:'★ Manual L'+manual,color:RTCRM.colors[manual],reason:'Manually assigned by the owner. Separate from evidence qualification.'};
  if(!RTCRM.completeness(e))return {level:'reference',label:'No contact route',color:colors.reference,reason:'Insufficient contact credibility: no email, phone, WhatsApp, social profile or website collected. No current trackable route.'};
  if(e.role==='Competition reference'||e.scope==='outside')return {level:'reference',label:'Reference / outside scope',color:colors.reference,reason:'Excluded from within-radius acquisition priorities.'};
  if(e.fit_group==='Exploratory')return {level:'low',label:'Low · exploratory',color:colors.low,reason:'Activity fit or audience suitability is weak or unresolved.'};
  if(e.fit_group==='Direct sport activity')return {level:'high',label:'High · review first',color:colors.high,reason:'A published badminton/pickleball activity makes the organiser directly relevant. Verify current needs and existing relationships.'};
  if(e.distance_km!=null&&e.distance_km<=3&&(e.phones?.length||e.emails?.length))return {level:'high',label:'High · review first',color:colors.high,reason:'Relevant category, within 3 km, with a public contact route. Demand, budget and decision maker are still unconfirmed.'};
  return {level:'medium',label:'Medium · research next',color:colors.medium,reason:'Relevant category, but distance, contact route or current programme suitability still needs checking.'};
 }
 function fail(message){const status=document.getElementById('map-status');if(status){status.className='notice';status.textContent=message}}
 window.gm_authFailure=()=>{authFailed=true;fail('Google Maps could not authorise this site. Check that Maps JavaScript API, billing and this website’s allowed referrer are enabled for the supplied key. The object list remains available.');};
 function load(){if(loader)return loader;loader=(async()=>{const r=await fetch('/api/maps-config',{cache:'no-store'});if(!r.ok)throw Error('Map configuration is unavailable.');const c=await r.json();if(!c.apiKey)throw Error('Google Maps key has not been configured.');await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('Google Maps loading timed out. The object list is still available.')),20000);window.__rainbowMapsReady=()=>{clearTimeout(timer);resolve()};const script=document.createElement('script');const q=new URLSearchParams({key:c.apiKey,loading:'async',callback:'__rainbowMapsReady',v:'weekly',language:'en',region:'AU'});script.src='https://maps.googleapis.com/maps/api/js?'+q;script.async=true;script.onerror=()=>{clearTimeout(timer);reject(Error('Google Maps could not load. Check your network or map settings.'))};document.head.append(script)});})();return loader}
 function popup(group,onSelect,onDetail){const wrap=document.createElement('div');wrap.className='map-popup';const heading=document.createElement('strong');heading.textContent=group.length>1?`${group.length} organisations at this published point`:group[0].name;wrap.append(heading);for(const e of group){const p=classify(e),row=document.createElement('div');row.className='map-popup-row';const title=document.createElement('h3');title.textContent=e.name;const badge=document.createElement('span');badge.className='priority-badge '+p.level;badge.textContent=p.label;const reason=document.createElement('p');reason.textContent=p.reason;const location=document.createElement('small');location.textContent=e.address+' · '+e.distance_km.toFixed(2)+' km';const button=document.createElement('button');button.textContent='View evidence';button.onclick=()=>{onSelect(e.id);onDetail(e.id)};row.append(title,badge,location,reason,button);wrap.append(row)}return wrap}
 async function draw({element,rows,center,onSelect,onDetail}){
  const ticket=++sequence;host=element;try{await load();if(ticket!==sequence||!element.isConnected)return;if(authFailed){window.gm_authFailure();return}
   // Reuse the same Maps instance across filters; it avoids extra billed map loads.
   if(map){element.replaceWith(host=map.getDiv());host.id='google-map'}else map=new google.maps.Map(element,{center:{lat:center.lat,lng:center.lon},zoom:12,mapTypeControl:false,streetViewControl:false,fullscreenControl:true,gestureHandling:'cooperative',clickableIcons:false});
   markers.forEach(m=>m.setMap(null));markers=[];byId.clear();if(info)info.close();info=new google.maps.InfoWindow();
   if(!map._researchRadius){map._researchRadius=new google.maps.Circle({map,center:{lat:center.lat,lng:center.lon},radius:10000,strokeColor:'#45546a',strokeWeight:1,strokeOpacity:.5,fillColor:'#60738a',fillOpacity:.035,clickable:false})}
   const venue=new google.maps.Marker({map,position:{lat:center.lat,lng:center.lon},title:'Rainbow Town · service venue',icon:{path:google.maps.SymbolPath.CIRCLE,scale:13,fillColor:'#172b4d',fillOpacity:1,strokeColor:'#fff',strokeWeight:3},label:{text:'R',color:'white',fontWeight:'700'},zIndex:10});venue.addListener('click',()=>{const p=document.createElement('div');p.textContent='Rainbow Town · 10 km research centre';const colocated=rows.filter(e=>Math.abs(e.lat-center.lat)<.00001&&Math.abs(e.lon-center.lon)<.00001);if(colocated.length)p.append(popup(colocated,onSelect,onDetail));info.setContent(p);info.open({map,anchor:venue})});markers.push(venue);
   const groups=new Map();rows.forEach(e=>{const k=e.lat.toFixed(5)+','+e.lon.toFixed(5);if(!groups.has(k))groups.set(k,[]);groups.get(k).push(e)});fitBounds=new google.maps.LatLngBounds();fitBounds.extend({lat:center.lat,lng:center.lon});
   groups.forEach(group=>{const order={manual1:0,high:1,manual2:2,medium:3,manual3:4,manual4:5,low:6,manual5:7,reference:8};group.sort((a,b)=>order[classify(a).level]-order[classify(b).level]);const e=group[0],p=classify(e),position={lat:e.lat,lng:e.lon};const marker=new google.maps.Marker({map,position,title:group.map(x=>x.name+' — '+classify(x).label).join('; '),icon:{path:p.level.startsWith('manual')?'M 0,-12 L 2.82,-3.88 L 11.41,-3.71 L 4.57,1.48 L 7.05,9.71 L 0,4.8 L -7.05,9.71 L -4.57,1.48 L -11.41,-3.71 L -2.82,-3.88 Z':google.maps.SymbolPath.CIRCLE,scale:p.level.startsWith('manual')?1.2:(group.length>1?11:8),fillColor:p.color,fillOpacity:.95,strokeColor:'#fff',strokeWeight:2},label:group.length>1?{text:String(group.length),color:'#fff',fontSize:'11px',fontWeight:'700'}:undefined,zIndex:100-order[p.level]*10,optimized:false});const open=(chosenId=e.id)=>{onSelect(chosenId);info.setContent(popup(group,onSelect,onDetail));info.open({map,anchor:marker})};marker.addListener('click',()=>open(e.id));group.forEach(x=>byId.set(x.id,{marker,open}));markers.push(marker);fitBounds.extend(position)});
   map.fitBounds(fitBounds,45);google.maps.event.addListenerOnce(map,'idle',()=>{if(map.getZoom()>15)map.setZoom(15)});
   const status=document.getElementById('map-status');if(status){status.className='map-note';status.textContent=`${rows.length} objects at ${groups.size} published points. Numbered markers contain multiple organisations; open them to see every record.`}
  }catch(e){if(ticket===sequence)fail(e.message)}
 }
 function select(id){const item=byId.get(id);if(item){map.panTo(item.marker.getPosition());item.open(id)}}
 function fit(){if(map&&fitBounds)map.fitBounds(fitBounds,45)}
 return {classify,draw,select,fit,load};
})();
